<script>
    import {base} from '$app/paths'

  let { path = undefined, data, ...rest } = $props();

    let buildPath = (path, target) => {
        let pathString = ''
        for (const place of path ) {
            if (place != target && place!= '' && place != '(sections)') {
                pathString = pathString + '/' + place
            } else if (place === target) {
                pathString = pathString + '/' + place
                break;
            }
        }
        return base + pathString;
    }

    let findPageTitle = (path, page) => {
      const builtPath = buildPath(path, page)
      let id = undefined;

      let title = undefined;

      for (const key of Object.keys(data)) {
        if (`/${data[key].link}` === builtPath) {
          // if data[key].title contains hyphen, replace it with space
          if (data[key].title.includes('-')) {
            title = data[key].title.replace(/-/g, ' ')
          } else {
            title = data[key].title;
          }
        }
      }
      if (id === undefined) {
        if (page.includes('-')) {
          title = page.replace(/-/g, ' ');
        } else {
          title = page;
        }
      }
      if (title) {
        return title.toLowerCase();
      } else {
        // throw an error if title is not found
        console.error(`Title not found for page: ${page}`);
      }
    };

</script>

<nav class={rest.class || "flex"} aria-label="Breadcrumb">
    <ol class="flex items-center space-x-2">
        {#each path as page}
            {#if page == ''}
            <li>
                <div>
                  <a href="{base}/" class="text-secondary-400 hover:text-secondary-500">
                    <svg class="h-5 w-5 flex-shrink-0" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                      <path fill-rule="evenodd" d="M9.293 2.293a1 1 0 011.414 0l7 7A1 1 0 0117 11h-1v6a1 1 0 01-1 1h-2a1 1 0 01-1-1v-3a1 1 0 00-1-1H9a1 1 0 00-1 1v3a1 1 0 01-1 1H5a1 1 0 01-1-1v-6H3a1 1 0 01-.707-1.707l7-7z" clip-rule="evenodd" />
                    </svg>
                    <span class="sr-only">Home</span>
                  </a>
                </div>
              </li>
              {:else if page != '(sections)'}
              <li>
                <div class="flex items-center">
                  <svg class="h-5 w-5 flex-shrink-0 text-secondary-400" viewBox="0 0 20 20" fill="currentColor" aria-hidden="true">
                    <path fill-rule="evenodd" d="M7.21 14.77a.75.75 0 01.02-1.06L11.168 10 7.23 6.29a.75.75 0 111.04-1.08l4.5 4.25a.75.75 0 010 1.08l-4.5 4.25a.75.75 0 01-1.06-.02z" clip-rule="evenodd" />
                  </svg>
                  <a href={buildPath(path, page)} class="ml-4 text-sm font-medium text-secondary-500 hover:text-secondary-800">{findPageTitle(path, page)}</a>
                </div>
              </li>
              {/if}

        {/each}   
    </ol>
  </nav>
  